//! API-coverage audit scenes: `tests/audit_scenes/audit_NNN.ops` (generated
//! by `tools/oracle/audit_scenes.py`) replayed through the port, every
//! diagram dump compared bit for bit with the real C++ (NDEBUG, bump
//! allocator) output in `tests/audit_scenes/golden/` (regenerated by
//! `tools/oracle/audit_scenes.sh`).  Scenes without a golden (upstream has
//! undefined behaviour on them: AddressSanitizer reports a use-after-free,
//! null dereference or buffer overflow) are only run, to check that the
//! port does not panic on them.
//!
//! `AUDIT_SCENE=audit_NNN` runs a single scene.

#![allow(clippy::uninlined_format_args)]

mod common;
#[path = "common/fixture_ops.rs"]
mod fixture_ops;

#[test]
fn audit_scenes_match_cpp() {
    let dir = format!("{}/tests/audit_scenes", env!("CARGO_MANIFEST_DIR"));
    let mut names: Vec<String> = std::fs::read_dir(&dir)
        .unwrap()
        .filter_map(|e| e.ok()?.file_name().into_string().ok()?.strip_suffix(".ops").map(String::from))
        .collect();
    names.sort();
    assert!(names.len() >= 100, "audit scenes missing");
    let only = std::env::var("AUDIT_SCENE").ok();
    let (mut ok, mut skipped) = (0, Vec::new());
    let mut failures = Vec::new();
    for name in names.iter() {
        if only.as_ref().is_some_and(|o| o != name) {
            continue;
        }
        if !std::path::Path::new(&format!("{}/golden/{}.exit", dir, name)).exists() {
            // Undefined behaviour upstream (see audit_scenes.sh): nothing to
            // compare, but the port must still run it without panicking.
            skipped.push(name.clone());
            let n = name.clone();
            if let Err(e) = std::panic::catch_unwind(move || fixture_ops::smoke_run_fixture(&n)) {
                failures.push(format!(
                    "{} (no C++ golden) panicked: {}",
                    name,
                    e.downcast_ref::<String>()
                        .cloned()
                        .or_else(|| e.downcast_ref::<&str>().map(|s| s.to_string()))
                        .unwrap_or_default()
                ));
            }
            continue;
        }
        let n = name.clone();
        match std::panic::catch_unwind(move || fixture_ops::run_fixture(&n)) {
            Ok(_) => ok += 1,
            Err(e) => failures.push(format!(
                "{}: {}",
                name,
                e.downcast_ref::<String>()
                    .cloned()
                    .or_else(|| e.downcast_ref::<&str>().map(|s| s.to_string()))
                    .unwrap_or_default()
            )),
        }
    }
    println!(
        "audit scenes: {} match, {} without C++ golden (run only: {:?}), {} failed",
        ok,
        skipped.len(),
        skipped,
        failures.len()
    );
    assert!(failures.is_empty(), "{} audit scene(s) differ:\n{}", failures.len(), failures.join("\n"));
}
